client.on("disconnected", (reason) => {
  console.error("[DISCONNECTED]", reason, "ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œ exiting for restart");
  if (reason === "LOGOUT") {
    try {
      console.log("User logged out. Clearing auth cache...");
      fs.rmSync(path.join(__dirname, ".wwebjs_auth"), {
        recursive: true,
        force: true,
      });
      fs.rmSync(path.join(__dirname, ".wwebjs_cache"), {
        recursive: true,
        force: true,
      });
    } catch (e) {
      console.error("Failed to clear cache:", e.message);
    }
  }
  process.exit(1);
});

